using System;using Autodesk.Revit.ApplicationServices;using Autodesk.Revit.DB;using SAUDICO.Federate.Core.Interfaces;using SAUDICO.Federate.Core.Models;using SAUDICO.Federate.Shared;namespace SAUDICO.Federate.ACC;
public sealed class CloudDocumentOpener:IDocumentOpener { public Document Open(ModelInfo m,Application app){if(!Guid.TryParse(m.ProjectGuid,out var p))throw new ArgumentException("Valid ACC Project GUID required.");if(!Guid.TryParse(m.ModelGuid,out var g))throw new ArgumentException("Valid ACC Model GUID required.");var region=m.Region==CloudRegion.US?ModelPathUtils.CloudRegionUS:ModelPathUtils.CloudRegionEMEA;var path=ModelPathUtils.ConvertCloudGUIDsToCloudPath(region,p,g);var op=new OpenOptions();op.SetOpenWorksetsConfiguration(new WorksetConfiguration(WorksetConfigurationOption.OpenAllWorksets));return app.OpenDocumentFile(path,op);} }
